Rewrite the following GNU C++20 (64) code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++20 (64) code you have to rewrite:
<original_code>
#include <stdio.h>
#include <algorithm>
#include <vector>
#include <string.h>
#define m1 998244353
#define m2 1000000007
#define MS 2000010
#define ll long long
using namespace std;
struct Set
{
    int sz[MS],n;ll H;
    void init(vector<ll> ve)
    {
        n=ve.size();H=0;
        for(int i=0;i<n;i++)
        {
            sz[i]=(ve[i]%m1+m1)%m1;
            H+=sz[i];
        }
        sort(sz,sz+n);
    }
    int ask(ll x)
    {
        x=(x%m1+m1)%m1;
        int l=0,r=n;
        while(l<r)
        {
            int m=(l+r)>>1;
            if(x+sz[m]>=m1)r=m;
            else l=m+1;
        }
        ll rt=H+1ll*x*n-1ll*m1*(n-l);
        return (rt%m2+m2)%m2;
    }
}se[15];ll tm,tt,mi[15],su[15];vector<ll> v0;
int sz[15];char zf[15];
void dfs0(int u,int s,int d)
{
    tm+=1;
    if(s==6)
    {
        v0.push_back(tm-u);
        tm+=su[d]-1;return;
    }
    for(int i=0;i<10;i++)
        dfs0(u*10+i,s+1,d);
}
int ans=0;
ll count(ll u,int s,int n,int eq)
{
    if(s>n||(s==n&&eq>0))return 0;
    if(eq>0)return su[n-s-1];
    if(eq<0)return su[n-s];
    ll rt=1;
    for(int i=0;i<10;i++)
        rt+=count(u*10+i,s+1,n,eq==0?i-sz[s]:eq);
    return rt;
}
void dfs3(ll u,int s,int d,int n,int eq)
{
    if(s>n||(s==n&&eq>0))return;
    tt+=1;
    if(d==6)
    {
        ans=(ans+((tt-u)%m1+m1)%m1)%m2;
        tt+=count(u,s,n,eq)-1;return;
    }
    for(int i=0;i<10;i++)
        dfs3(u*10+i,s+1,d+1,n,eq==0?i-sz[s]:eq);
}
void dfs1(int u,int s,int n,int eq)
{
    if(s>n||(s==n&&eq>0))return;
    tm+=1;
    if(s+6<=n)
    {
        if(eq>0)
            ans=(ans+(n>=s-7?se[n-s-7].ask(tm-1ll*u*1000000):0))%m2;
        else if(eq<0)
            ans=(ans+se[n-s-6].ask(tm-1ll*u*1000000))%m2;
        else
        {
            tt=tm-1;
            dfs3(u,s,0,n,eq);
        }
    }
    ans=(ans+((tm-u)%m1+m1)%m1)%m2;
    if(s==6)
    {
        tm+=count(u,s,n,eq)-1;
        return;
    }
    if(s==n)return;
    for(int i=0;i<10;i++)
        dfs1(u*10+i,s+1,n,eq==0?i-sz[s]:eq);
}
int main()
{
    mi[0]=su[0]=1;
    for(int i=1;i<=12;i++)
    {
        mi[i]=10*mi[i-1];
        su[i]=su[i-1]+mi[i];
    }
    scanf("%s",zf);int n=strlen(zf);
    if(n==13)
    {
        printf("289817887");
        return 0;
    }
    for(int i=0;i<n;i++)sz[i]=zf[i]-'0';
    for(int i=0;i<=n-6;i++)
    {
        tm=-1;v0.clear();
        dfs0(0,0,i);se[i].init(v0);
    }
    tm=0;
    for(int i=1;i<=9;i++)
        dfs1(i,1,n,i-sz[0]);
    printf("%d",ans);
    return 0;
}
//I love Set forever
